-- Ferrum Capital nümunə layihəsi — SQL Server üçün
-- İstifadə: SSMS-də aç və F5 bas. Əvvəlcə FerrumDemo bazası yaradılır.
-- Data saxtadır (uydurmadır), yalnız məşq üçündür. Hesabat tarixi: 2026-09-30.

IF DB_ID('FerrumDemo') IS NULL CREATE DATABASE FerrumDemo;
GO
USE FerrumDemo;
GO
DROP TABLE IF EXISTS payments, contracts, applications, customers, partners;
GO
CREATE TABLE partners (
  partner_id INT PRIMARY KEY, partner_name NVARCHAR(100), sector NVARCHAR(60), city NVARCHAR(50),
  join_date DATE, account_manager NVARCHAR(60));
-- Diqqət: customers cədvəlində PRIMARY KEY yoxdur — içində təkrarlanan sətirlər var (qəsdən).
CREATE TABLE customers (
  customer_id INT, full_name NVARCHAR(100), gender NVARCHAR(10), birth_date NVARCHAR(20), city NVARCHAR(50),
  phone NVARCHAR(30), monthly_income DECIMAL(10,2) NULL, registration_date DATE);
CREATE TABLE applications (
  application_id INT PRIMARY KEY, customer_id INT, partner_id INT, application_date DATE, requested_amount DECIMAL(12,2),
  term_months INT, product NVARCHAR(40), status NVARCHAR(20), reject_reason NVARCHAR(60) NULL);
CREATE TABLE contracts (
  contract_id INT PRIMARY KEY, application_id INT, customer_id INT, partner_id INT, product NVARCHAR(40), start_date DATE,
  amount DECIMAL(12,2), term_months INT, monthly_rate DECIMAL(6,4), total_payable DECIMAL(12,2), monthly_payment DECIMAL(12,2));
CREATE TABLE payments (
  payment_id INT PRIMARY KEY, contract_id INT, installment_no INT, due_date DATE, due_amount DECIMAL(12,2),
  paid_date DATE NULL, paid_amount DECIMAL(12,2) NULL);
GO
SET NOCOUNT ON;

